package com.example.payment.integrationtest.paymentgateway;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import com.example.payment.domain.AuthorizationOutcome;
import com.example.payment.domain.Money;
import com.example.payment.infrastructure.HttpPaymentGateway;
import java.math.BigDecimal;
import okhttp3.mockwebserver.MockResponse;
import okhttp3.mockwebserver.MockWebServer;
import okhttp3.mockwebserver.RecordedRequest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.web.client.RestClient;

/**
 * Exercises HttpPaymentGateway against a real HTTP server (MockWebServer) to prove the request
 * we send and the responses we read back are wired correctly, including the provider's decline
 * (402) path and unexpected error responses.
 */
class HttpPaymentGatewayTest {

    private MockWebServer server;
    private HttpPaymentGateway gateway;

    @BeforeEach
    void startServer() throws Exception {
        server = new MockWebServer();
        server.start();
        var client = RestClient.builder().baseUrl(server.url("/").toString()).build();
        gateway = new HttpPaymentGateway(client);
    }

    @AfterEach
    void stopServer() throws Exception {
        server.shutdown();
    }

    @Test
    void sends_the_reference_amount_and_currency_as_json_to_the_authorizations_endpoint() throws Exception {
        server.enqueue(new MockResponse()
                .setResponseCode(200)
                .setBody("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json"));

        gateway.authorize("ORD-1", new Money(new BigDecimal("12.50"), "eur"));

        RecordedRequest recorded = server.takeRequest();
        assertThat(recorded.getMethod()).isEqualTo("POST");
        assertThat(recorded.getPath()).isEqualTo("/v1/authorizations");
        assertThat(recorded.getHeader("Content-Type")).contains("application/json");
        assertThat(recorded.getBody().readUtf8())
                .isEqualTo("{\"reference\":\"ORD-1\",\"amount\":12.50,\"currency\":\"EUR\"}");
    }

    @Test
    void an_approved_response_is_read_back_as_approved() {
        server.enqueue(new MockResponse()
                .setResponseCode(200)
                .setBody("{\"status\":\"approved\"}")
                .addHeader("Content-Type", "application/json"));

        var outcome = gateway.authorize("ORD-2", new Money(new BigDecimal("10"), "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.APPROVED);
    }

    @Test
    void a_declined_response_is_read_back_as_declined() {
        server.enqueue(new MockResponse()
                .setResponseCode(200)
                .setBody("{\"status\":\"declined\"}")
                .addHeader("Content-Type", "application/json"));

        var outcome = gateway.authorize("ORD-3", new Money(new BigDecimal("10"), "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void the_provider_refusing_the_payment_with_402_is_read_back_as_declined() {
        server.enqueue(new MockResponse().setResponseCode(402).setBody("{\"error\":\"insufficient_funds\"}"));

        var outcome = gateway.authorize("ORD-4", new Money(new BigDecimal("10"), "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }

    @Test
    void an_unexpected_error_status_from_the_provider_fails_loudly_instead_of_silently_declining() {
        server.enqueue(new MockResponse().setResponseCode(500).setBody("boom"));

        assertThatThrownBy(() -> gateway.authorize("ORD-5", new Money(new BigDecimal("10"), "USD")))
                .isInstanceOf(IllegalStateException.class)
                .hasMessageContaining("500");
    }

    @Test
    void a_response_body_missing_the_status_field_is_read_back_as_declined() {
        server.enqueue(new MockResponse()
                .setResponseCode(200)
                .setBody("{}")
                .addHeader("Content-Type", "application/json"));

        var outcome = gateway.authorize("ORD-6", new Money(new BigDecimal("10"), "USD"));

        assertThat(outcome).isEqualTo(AuthorizationOutcome.DECLINED);
    }
}
